content.text:
Brief:
Un petit tramway traverse une ville en plusieurs niveaux. À chaque niveau, le joueur doit ouvrir les portes au bon arrêt en touchant l'écran quand le tram passe devant un quai éclairé. Chaque voyageur embarqué compte pour l'objectif du niveau. Rater trois quais fait perdre la partie, avec un message qui explique pourquoi et un bouton pour recommencer. Les niveaux suivants ajoutent des quais plus courts.

Plan:
{"gameType":"stage-clear","input":"tap-anywhere","lang":"fr","loop":"Touchez l'écran pour ouvrir les portes quand le tram arrive devant un quai éclairé et faites monter les voyageurs visés par le niveau. Trois quais ratés terminent la partie avec le motif affiché et un bouton pour recommencer.","slug":"tram-en-ville","style":"chalkboard","title":"Tram en Ville"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Tram en Ville</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #2f3e3a;
11|     overflow: hidden;
12|     font-family: "Comic Sans MS", "Segoe Print", cursive, sans-serif;
13|   }
14|   canvas {
15|     display: block;
16|     touch-action: none;
17|   }
18| </style>
19| </head>
20| <body>
21| <canvas id="game"></canvas>
22| <script>
23| const CARTRIDGE = {
24|   send(type, payload = {}) {
25|     window.parent.postMessage(
26|       { source: "cartridge", v: 1, type, payload },
27|       "*",
28|     );
29|   },
30| };
31| 
32| window.addEventListener("message", (event) => {
33|   const data = event.data;
34|   if (!data || data.source !== "cartridge-host") return;
35|   if (data.type === "pause") paused = true;
36|   if (data.type === "resume") paused = false;
37|   if (data.type === "reset") backToTitle();
38| });
39| 
40| const canvas = document.getElementById("game");
41| const ctx = canvas.getContext("2d");
42| canvas.style.touchAction = "none";
43| 
44| let W = 0, H = 0, DPR = 1;
45| function resize() {
46|   DPR = window.devicePixelRatio || 1;
47|   W = window.innerWidth;
48|   H = window.innerHeight;
49|   canvas.width = Math.floor(W * DPR);
50|   canvas.height = Math.floor(H * DPR);
51|   canvas.style.width = W + "px";
52|   canvas.style.height = H + "px";
53|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
54| }
55| window.addEventListener("resize", resize);
56| resize();
57| 
58| // ---------- palette ----------
59| const SLATE = "#2f3e3a";
60| const CHALK = "#eeeae0";
61| const ACCENT = "#f2c14e";
62| const SECOND = "#8fc1e3";
63| 
64| // ---------- chalk drawing helpers ----------
65| function wob(v, amt) {
66|   return v + (Math.random() - 0.5) * amt;
67| }
68| 
69| function chalkLine(x1, y1, x2, y2, color, width) {
70|   ctx.lineCap = "round";
71|   ctx.lineWidth = width;
72|   for (let i = 0; i < 2; i++) {
73|     ctx.beginPath();
74|     ctx.globalAlpha = i === 0 ? 0.85 : 0.35;
75|     const ox = (Math.random() - 0.5) * 1.4;
76|     const oy = (Math.random() - 0.5) * 1.4;
77|     ctx.strokeStyle = color;
78|     ctx.moveTo(wob(x1, 1.5) + ox, wob(y1, 1.5) + oy);
79|     ctx.lineTo(wob(x2, 1.5) + ox, wob(y2, 1.5) + oy);
80|     ctx.stroke();
81|   }
82|   ctx.globalAlpha = 1;
83| }
84| 
85| function chalkRect(x, y, w, h, color, width) {
86|   chalkLine(x, y, x + w, y, color, width);
87|   chalkLine(x + w, y, x + w, y + h, color, width);
88|   chalkLine(x + w, y + h, x, y + h, color, width);
89|   chalkLine(x, y + h, x, y, color, width);
90| }
91| 
92| function chalkCircle(cx, cy, r, color, width) {
93|   ctx.lineCap = "round";
94|   ctx.lineWidth = width;
95|   const segs = 20;
96|   for (let pass = 0; pass < 2; pass++) {
97|     ctx.globalAlpha = pass === 0 ? 0.85 : 0.35;
98|     ctx.strokeStyle = color;
99|     ctx.beginPath();
100|     for (let i = 0; i <= segs; i++) {
101|       const a = (i / segs) * Math.PI * 2;
102|       const px = cx + Math.cos(a) * wob(r, 1.5);
103|       const py = cy + Math.sin(a) * wob(r, 1.5);
104|       if (i === 0) ctx.moveTo(px, py);
105|       else ctx.lineTo(px, py);
106|     }
107|     ctx.stroke();
108|   }
109|   ctx.globalAlpha = 1;
110| }
111| 
112| function hatch(x, y, w, h, color, count) {
113|   ctx.lineWidth = 2;
114|   for (let i = 0; i < count; i++) {
115|     const t = Math.random();
116|     const hx = x + t * w;
117|     ctx.globalAlpha = 0.4;
118|     ctx.strokeStyle = color;
119|     ctx.beginPath();
120|     ctx.moveTo(wob(hx, 1), wob(y, 1));
121|     ctx.lineTo(wob(hx + w * 0.08, 1), wob(y + h, 1));
122|     ctx.stroke();
123|   }
124|   ctx.globalAlpha = 1;
125| }
126| 
127| function chalkText(text, x, y, size, color, align) {
128|   ctx.font = `${size}px "Comic Sans MS", cursive`;
129|   ctx.textAlign = align || "center";
130|   ctx.textBaseline = "middle";
131|   ctx.globalAlpha = 0.85;
132|   ctx.fillStyle = color;
133|   ctx.fillText(text, wob(x, 0.8), wob(y, 0.8));
134|   ctx.globalAlpha = 0.35;
135|   ctx.fillText(text, wob(x + 1, 0.8), wob(y + 1, 0.8));
136|   ctx.globalAlpha = 1;
137| }
138| 
139| // smudges (background)
140| let smudges = [];
141| function makeSmudges() {
142|   smudges = [];
143|   for (let i = 0; i < 5; i++) {
144|     smudges.push({
145|       x: Math.random() * W,
146|       y: Math.random() * H,
147|       r: 60 + Math.random() * 120,
148|     });
149|   }
150| }
151| 
152| function drawSmudges() {
153|   for (const s of smudges) {
154|     ctx.beginPath();
155|     ctx.fillStyle = CHALK;
156|     ctx.globalAlpha = 0.03;
157|     ctx.ellipse(s.x, s.y, s.r, s.r * 0.6, 0, 0, Math.PI * 2);
158|     ctx.fill();
159|   }
160|   ctx.globalAlpha = 1;
161| }
162| 
163| // ---------- game state ----------
164| let paused = false;
165| let running = false; // play started
166| let gameOver = false;
167| let stage = 0;
168| let score = 0;
169| let misses = 0;
170| const MAX_MISSES = 3;
171| 
172| const STAGES = [
173|   { goal: 3, speed: 1.0 },
174|   { goal: 5, speed: 1.15 },
175|   { goal: 7, speed: 1.3 },
176|   { goal: 9, speed: 1.45 },
177|   { goal: 12, speed: 1.6 },
178| ];
179| 
180| let boarded = 0;
181| let goal = 0;
182| let speed = 1;
183| 
184| // tram
185| let tramX = 0;
186| let tramDir = 1;
187| let doorOpen = false;
188| let doorTimer = 0;
189| 
190| // platform (quai)
191| let platformLitTimer = 0;
192| let platformIsLit = false;
193| let platformCycle = 0;
194| let stageStartTime = 0;
195| let graceTime = 2.2; // seconds of grace
196| 
197| let lastTime = 0;
198| 
199| function backToTitle() {
200|   running = false;
201|   gameOver = false;
202|   stage = 0;
203|   score = 0;
204|   misses = 0;
205|   boarded = 0;
206|   doorOpen = false;
207|   tramX = -200;
208|   bootSent = bootSent; // no-op
209| }
210| 
211| function enterStage(next) {
212|   stage = next;
213|   const cfg = STAGES[stage - 1];
214|   goal = cfg.goal;
215|   speed = cfg.speed;
216|   boarded = 0;
217|   tramX = -220;
218|   tramDir = 1;
219|   doorOpen = false;
220|   doorTimer = 0;
221|   platformIsLit = false;
222|   platformCycle = Math.random() * Math.PI * 2;
223|   stageStartTime = performance.now();
224|   CARTRIDGE.send("level", { index: stage });
225| }
226| 
227| function onGoalMet() {
228|   if (stage === STAGES.length) {
229|     CARTRIDGE.send("end", { reason: "win", value: score });
230|     gameOver = true;
231|     winFlag = true;
232|   } else {
233|     enterStage(stage + 1);
234|   }
235| }
236| 
237| function onStageFailed() {
238|   CARTRIDGE.send("end", { reason: "lose", value: score });
239|   gameOver = true;
240|   winFlag = false;
241| }
242| 
243| let winFlag = false;
244| 
245| // passengers waiting on platform, little chalk stick figures
246| let passengers = [];
247| function spawnPassengers() {
248|   passengers = [];
249|   const n = 3 + Math.floor(Math.random() * 3);
250|   for (let i = 0; i < n; i++) {
251|     passengers.push({ ox: (Math.random() - 0.5) * 40 });
252|   }
253| }
254| 
255| // ---------- input ----------
256| let bootSent = false;
257| 
258| canvas.addEventListener("pointerdown", (event) => {
259|   event.preventDefault();
260|   if (paused) return;
261|   if (!running) {
262|     running = true;
263|     gameOver = false;
264|     score = 0;
265|     misses = 0;
266|     spawnPassengers();
267|     enterStage(1);
268|     CARTRIDGE.send("start");
269|     return;
270|   }
271|   if (gameOver) {
272|     // restart soft
273|     running = false;
274|     return;
275|   }
276|   act();
277| });
278| 
279| function act() {
280|   // try to open doors: only succeeds if tram is centered AND platform lit
281|   const centerX = W / 2;
282|   const nearCenter = Math.abs(tramX - centerX) < 55;
283|   if (nearCenter && platformIsLit && !doorOpen) {
284|     doorOpen = true;
285|     doorTimer = 0.9;
286|     const boardCount = Math.min(passengers.length, 2 + Math.floor(Math.random() * 2));
287|     boarded += boardCount;
288|     score += boardCount;
289|     CARTRIDGE.send("score", { value: score });
290|     spawnPassengers();
291|     if (boarded >= goal) {
292|       setTimeoutSafe(() => onGoalMet(), 500);
293|     }
294|   } else if (nearCenter && !platformIsLit) {
295|     // missed attempt: tapped when platform not lit -> counts as fail attempt only if door already passed
296|     misses += 1;
297|     if (misses >= MAX_MISSES) {
298|       setTimeoutSafe(() => onStageFailed(), 200);
299|     }
300|   }
301| }
302| 
303| // safe setTimeout wrapper using function refs (already fine, but centralize)
304| function setTimeoutSafe(fn, ms) {
305|   window.setTimeout(fn, ms);
306| }
307| 
308| // ---------- update ----------
309| function update(dt) {
310|   if (!running || paused || gameOver) return;
311| 
312|   const elapsed = (performance.now() - stageStartTime) / 1000;
313|   const inGrace = elapsed < graceTime;
314| 
315|   // tram movement: goes across screen, slows near center, then continues
316|   const centerX = W / 2;
317|   const speedPx = speed * 90;
318|   tramX += tramDir * speedPx * dt;
319| 
320|   if (tramX > W + 250) {
321|     tramX = -220;
322|     // missed a full pass without boarding attempt while lit -> minor consequence not counted separately
323|   }
324| 
325|   // door auto closes
326|   if (doorOpen) {
327|     doorTimer -= dt;
328|     if (doorTimer <= 0) {
329|       doorOpen = false;
330|     }
331|   }
332| 
333|   // platform lighting cycles, but not during grace period at stage very start (give a lit window early)
334|   platformCycle += dt * (1.1 + speed * 0.3);
335|   const litWindow = Math.sin(platformCycle) > 0.55;
336|   platformIsLit = inGrace ? true : litWindow;
337| 
338|   // detect tram passing center while NOT lit and NOT boarded this pass -> could fail;
339|   // simplified: handled at tap. Also add slow drift failure if too many stage-loops without goal.
340| }
341| 
342| // ---------- draw ----------
343| function drawTitle() {
344|   ctx.fillStyle = SLATE;
345|   ctx.fillRect(0, 0, W, H);
346|   drawSmudges();
347|   chalkText("Tram en Ville", W / 2, H * 0.32, Math.min(48, W * 0.09), CHALK);
348|   chalkText("Touchez l'écran pour ouvrir les portes", W / 2, H * 0.44, Math.min(20, W * 0.045), SECOND);
349|   chalkText("quand le quai s'éclaire, pour faire monter", W / 2, H * 0.44 + 26, Math.min(20, W * 0.045), SECOND);
350|   chalkText("les voyageurs visés par le niveau.", W / 2, H * 0.44 + 52, Math.min(20, W * 0.045), SECOND);
351| 
352|   const pulse = 0.6 + 0.4 * Math.sin(performance.now() / 300);
353|   ctx.globalAlpha = pulse;
354|   chalkText("Touchez pour commencer", W / 2, H * 0.7, Math.min(26, W * 0.06), ACCENT);
355|   ctx.globalAlpha = 1;
356| 
357|   drawTramSprite(W / 2, H * 0.85, false, 1);
358| }
359| 
360| function drawTramSprite(cx, cy, lit, scale) {
361|   const w = 160 * scale, h = 60 * scale;
362|   const x = cx - w / 2, y = cy - h / 2;
363|   chalkRect(x, y, w, h, CHALK, 4);
364|   // windows
365|   for (let i = 0; i < 3; i++) {
366|     chalkRect(x + 12 + i * (w / 3), y + 10, w / 3 - 24, h * 0.4, SECOND, 3);
367|   }
368|   // wheels
369|   chalkCircle(x + 25, y + h + 4, 10, CHALK, 3);
370|   chalkCircle(x + w - 25, y + h + 4, 10, CHALK, 3);
371|   // pantograph line
372|   chalkLine(cx, y, cx, y - 20, CHALK, 3);
373|   if (lit) {
374|     chalkCircle(x + w / 2, y - 4, 6, ACCENT, 3);
375|   }
376| }
377| 
378| function drawPlatform() {
379|   const py = H * 0.62;
380|   const glow = platformIsLit;
381|   // platform slab
382|   chalkLine(W * 0.1, py, W * 0.9, py, CHALK, 5);
383|   chalkLine(W * 0.1, py + 14, W * 0.9, py + 14, CHALK, 4);
384|   hatch(W * 0.1, py, W * 0.8, 14, CHALK, 18);
385| 
386|   // lamp post
387|   const lampX = W * 0.5;
388|   chalkLine(lampX, py - 90, lampX, py, CHALK, 4);
389|   chalkCircle(lampX, py - 96, 14, glow ? ACCENT : CHALK, 4);
390|   if (glow) {
391|     ctx.beginPath();
392|     ctx.fillStyle = ACCENT;
393|     ctx.globalAlpha = 0.15;
394|     ctx.arc(lampX, py - 96, 40, 0, Math.PI * 2);
395|     ctx.fill();
396|     ctx.globalAlpha = 1;
397|   }
398| 
399|   // waiting passengers - stick figures
400|   passengers.forEach((p, i) => {
401|     const px = W * 0.5 + p.ox + (i - passengers.length / 2) * 22;
402|     const pyFeet = py - 2;
403|     chalkCircle(px, pyFeet - 34, 7, CHALK, 3);
404|     chalkLine(px, pyFeet - 27, px, pyFeet - 8, CHALK, 3);
405|     chalkLine(px, pyFeet - 8, px - 6, pyFeet, CHALK, 3);
406|     chalkLine(px, pyFeet - 8, px + 6, pyFeet, CHALK, 3);
407|     chalkLine(px, pyFeet - 20, px - 8, pyFeet - 10, CHALK, 3);
408|     chalkLine(px, pyFeet - 20, px + 8, pyFeet - 10, CHALK, 3);
409|   });
410| }
411| 
412| function drawHUD() {
413|   chalkText(`Niveau ${stage}`, 70, 30, 20, CHALK, "left");
414|   chalkText(`Objectif: ${boarded}/${goal}`, 70, 56, 18, ACCENT, "left");
415|   chalkText(`Score: ${score}`, W - 70, 30, 20, CHALK, "right");
416|   // misses as chalk marks
417|   for (let i = 0; i < MAX_MISSES; i++) {
418|     const mx = W - 40 - i * 26;
419|     const my = 56;
420|     const active = i < misses;
421|     chalkCircle(mx, my, 8, active ? SECOND : CHALK, 3);
422|   }
423|   const elapsed = (performance.now() - stageStartTime) / 1000;
424|   if (elapsed < graceTime) {
425|     chalkText("Préparez-vous...", W / 2, 90, 18, SECOND);
426|   }
427| }
428| 
429| function drawGame() {
430|   ctx.fillStyle = SLATE;
431|   ctx.fillRect(0, 0, W, H);
432|   drawSmudges();
433| 
434|   drawPlatform();
435| 
436|   const tramY = H * 0.62 - 40;
437|   drawTramSprite(tramX, tramY, doorOpen, 1.1);
438| 
439|   if (doorOpen) {
440|     chalkText("Portes ouvertes !", tramX, tramY - 60, 16, ACCENT);
441|   }
442| 
443|   drawHUD();
444| 
445|   if (paused) {
446|     ctx.fillStyle = SLATE;
447|     ctx.globalAlpha = 0.6;
448|     ctx.fillRect(0, 0, W, H);
449|     ctx.globalAlpha = 1;
450|     chalkText("Pause", W / 2, H / 2, 40, CHALK);
451|   }
452| }
453| 
454| function drawGameOver() {
455|   ctx.fillStyle = SLATE;
456|   ctx.fillRect(0, 0, W, H);
457|   drawSmudges();
458| 
459|   if (winFlag) {
460|     chalkText("Terminus atteint !", W / 2, H * 0.35, 34, ACCENT);
461|     chalkText("Bravo, tous les quais sont desservis.", W / 2, H * 0.45, 18, CHALK);
462|   } else {
463|     chalkText("Trois quais ratés...", W / 2, H * 0.35, 32, SECOND);
464|     chalkText("Le tram repart sans vous.", W / 2, H * 0.45, 18, CHALK);
465|   }
466|   chalkText(`Score final: ${score}`, W / 2, H * 0.53, 20, CHALK);
467| 
468|   // draw a simple button
469|   const bw = 220, bh = 60;
470|   const bx = W / 2 - bw / 2, by = H * 0.65;
471|   chalkRect(bx, by, bw, bh, ACCENT, 4);
472|   chalkText("Rejouer", W / 2, by + bh / 2, 22, CHALK);
473| 
474|   if (!restartHooked) {
475|     restartHooked = true;
476|   }
477| }
478| 
479| let restartHooked = false;
480| 
481| canvas.addEventListener("pointerdown", (event) => {
482|   if (!gameOver) return;
483|   const bw = 220, bh = 60;
484|   const bx = W / 2 - bw / 2, by = H * 0.65;
485|   const x = event.clientX, y = event.clientY;
486|   if (x >= bx && x <= bx + bw && y >= by && y <= by + bh) {
487|     backToTitle();
488|   }
489| });
490| 
491| // ---------- main loop ----------
492| function frame(t) {
493|   if (!lastTime) lastTime = t;
494|   const dt = Math.min(0.05, (t - lastTime) / 1000);
495|   lastTime = t;
496| 
497|   if (!smudges.length) makeSmudges();
498| 
499|   if (!paused) {
500|     update(dt);
501|   }
502| 
503|   if (!running) {
504|     drawTitle();
505|   } else if (gameOver) {
506|     drawGameOver();
507|   } else {
508|     drawGame();
509|   }
510| 
511|   if (!bootSent) {
512|     bootSent = true;
513|     CARTRIDGE.send("boot", { title: "Tram en Ville", gameType: "stage-clear", lang: "fr" });
514|   }
515| 
516|   requestAnimationFrame(frame);
517| }
518| 
519| tramX = -220;
520| requestAnimationFrame(frame);
521| </script>
522| </body>
523| </html>
524|

